const steps={飯:['將蔬菜洗淨切好，白米先煮熟；若使用熟飯則直接備用。','依所列食材煮熟肉類、蛋或豆類，再加入蔬菜與調味料。','與飯一起盛盤；炊飯或燉飯則加水煮至米粒熟透。'],麵:['將所列麵條依包裝指示煮熟。','把蔬菜、肉類或豆類煮熟；涼拌食材另外洗淨處理。','加入所列調味料拌勻；湯麵加入水煮開後盛碗。'],湯:['把所列食材洗淨切好；白飯另行煮熟。','先煮耐煮的根莖、肉類或豆類，再加入其餘食材。','煮至食材熟透並用所列調味料調味；濃湯可攪打後食用。'],輕食:['將食材洗淨切好；生菜與熟食使用乾淨器具分開處理。','肉、蛋、豆類與根莖先煮熟；即食水果與乳製品不需加熱。','依餐點名稱組合成沙拉、吐司或飯碗，以所列材料調味。']};
const recipeSteps=[["番茄切塊，雞蛋打散。", "熱油炒蛋盛起，再炒軟番茄，加鹽並放回雞蛋，搭配熟飯。"], ["香菇與青江菜切好，豆腐切塊。", "熱油炒香菇，加少量水、豆腐及青江菜煮熟；用玉米澱粉水勾薄芡，加鹽淋飯。"], ["雞肉切片，檸檬擠汁，花椰菜切小朵。", "雞肉用油煎至熟透，花椰菜燙熟；淋檸檬汁、加鹽後配飯。"], ["豬肉切片，薑與青蔥切細，高麗菜切片。", "熱油炒薑、豬肉及高麗菜至熟透，加入青蔥與鹽，搭配熟飯。"], ["鮭魚擦乾，花椰菜與紅蘿蔔切好。", "鮭魚用油煎至熟透，蔬菜燙熟，加鹽後與熟飯盛盤。"], ["白米洗淨，南瓜切小塊，鴻喜菇剝散。", "米加平常煮飯用水量，放入南瓜、菇、油與鹽，一起煮至熟透並拌勻。"], ["彩椒切丁，玉米與青豆備好。", "熱油炒熟蔬菜，放入熟飯拌炒，加鹽調味。"], ["毛豆煮熟，小黃瓜洗淨切片，海苔剪碎。", "將毛豆與小黃瓜放在熟飯上，加少許鹽、撒上海苔。"], ["牛肉與洋蔥切薄片。", "熱油炒洋蔥至軟，加入牛肉炒熟，再加醬油與少量水，淋在熟飯上。"], ["雞肉及紅蘿蔔切小丁，雞蛋打散。", "先炒雞肉與紅蘿蔔至熟，再炒入蛋、熟飯與青蔥，加鹽拌勻。"], ["使用煮熟的鷹嘴豆，番茄切丁。", "熱油炒番茄與薑黃、孜然，加入鷹嘴豆煮熱，加鹽後配飯。"], ["菠菜、紅蘿蔔與黃豆芽分別燙熟瀝乾。", "鋪在熟飯上，加入芝麻油、芝麻及鹽，食用時拌勻。"], ["蝦去殼，蒜與蔥切細，雞蛋打散。", "熱油炒蒜和蝦至熟，加入蛋、熟飯及蔥拌炒，加鹽。"], ["牛肉切小塊，番茄與洋蔥切丁，米洗淨。", "炒洋蔥、牛肉及番茄，加米與水燉煮，視情況補水，煮至米與肉熟透後加鹽。"], ["豆腐加油煎熟，酪梨與小黃瓜切片。", "與熟飯一起盛碗，以檸檬汁及鹽調味。"], ["義大利麵依包裝指示煮熟，菇與蒜切好。", "橄欖油炒香蒜和菇，加入麵及少量煮麵水，加鹽拌勻。"], ["義大利麵煮熟，番茄、櫛瓜及洋蔥切丁。", "橄欖油炒洋蔥，放入番茄與櫛瓜燜熟，再拌入麵及鹽。"], ["米粉依包裝指示處理，雞肉、高麗菜及薑切好。", "水煮開後放入雞肉與薑，煮熟後加入高麗菜、米粉與鹽，續煮至熟。"], ["米粉依包裝指示處理，香菇、青菜及紅蘿蔔切好。", "水煮開加入香菇及紅蘿蔔，再加入米粉與青菜，煮熟後加鹽。"], ["小麥麵條煮熟瀝乾，小黃瓜及紅蘿蔔切絲。", "芝麻醬、醬油及米醋加少量水拌開，與麵及蔬菜拌勻。"], ["麵條先煮熟，豬肉、高麗菜及青蔥切好。", "油炒豬肉和高麗菜至熟，加入麵條、青蔥及鹽拌炒。"], ["將水煮開，加入豆腐、菇與烏龍麵煮熟。", "加入青江菜煮熟，轉小火，將味噌拌入湯中。"], ["冬粉泡軟，蝦去殼，高麗菜及薑切好。", "水煮開，加入薑、蝦和高麗菜煮熟，再加冬粉與鹽煮透。"], ["米粉煮熟瀝乾，小黃瓜切絲。", "花生醬以水調開，加入米醋與鹽，拌入米粉及小黃瓜。"], ["義大利麵煮熟，蘑菇切片。", "橄欖油炒熟蘑菇，加入牛奶、起司及少量煮麵水，拌入麵與鹽。"], ["高麗菜與紅蘿蔔切好，豆腐切塊，金針菇去根。", "水煮開後加入所有鍋料煮熟，加鹽並搭配熟飯。"], ["雞肉、番茄及洋蔥切小塊。", "放入水中煮至雞肉熟透、蔬菜軟化，加鹽並搭配熟飯。"], ["南瓜、馬鈴薯與洋蔥切小塊，使用熟鷹嘴豆。", "橄欖油炒洋蔥，再加入其餘食材與水煮軟；攪打成濃湯後加鹽。"], ["鯛魚切片，薑切絲，青蔥切細。", "水加薑煮開，放魚片煮熟，再加青蔥與鹽，搭配熟飯。"], ["白蘿蔔切小塊，豬肉切片，薑切片。", "水煮開後加入食材，煮至蘿蔔軟、豬肉熟透，加鹽搭配熟飯。"], ["海帶依包裝泡發處理，豆腐切塊，薑切絲。", "放入水中煮熟，以鹽調味並搭配熟飯。"], ["水煮開後加入玉米，雞蛋打散。", "緩緩倒入蛋液並煮熟，加青蔥與鹽，搭配熟飯。"], ["雞肉用橄欖油煎至熟透，馬鈴薯切塊煮熟。", "生菜、番茄及小黃瓜洗淨切好，與雞肉、馬鈴薯盛盤，淋檸檬汁及鹽。"], ["使用煮熟的鷹嘴豆和玉米，小黃瓜與番茄洗淨切丁。", "全部拌在一起，用檸檬汁、橄欖油與鹽調味。"], ["地瓜切塊蒸熟，毛豆煮熟，紅蘿蔔切絲燙熟。", "搭配洗淨的生菜，以橄欖油與鹽調味。"], ["雞蛋煮熟去殼壓碎，拌入原味優格與鹽。", "將洗淨瀝乾的生菜和蛋沙拉夾入純素小麥吐司。"], ["番茄切片，生菜洗淨瀝乾。", "將起司、番茄及生菜夾入純素小麥吐司，可稍微烘烤。"], ["豆腐燙熟瀝乾，生菜、小黃瓜及紅蘿蔔洗淨切絲。", "米紙短暫沾水變軟後包入食材，搭配米醋與鹽。"], ["蝦煮熟去殼，生菜、小黃瓜及紅蘿蔔洗淨切絲。", "米紙沾水變軟，包入蝦和蔬菜，搭配檸檬汁及鹽。"], ["藜麥依包裝比例加水煮熟放涼。", "拌入洗淨的生菜、番茄與核桃，以檸檬汁、橄欖油及鹽調味。"], ["地瓜切小塊蒸熟。", "雞蛋煮至全熟後去殼，與地瓜一起盛盤。"], ["燕麥加入牛奶，以小火煮軟。", "香蕉切片鋪在煮好的燕麥上。"], ["燕麥加入無糖豆漿，以小火煮軟。", "蘋果洗淨切丁，加入燕麥拌勻。"], ["麵粉加水與少許鹽調成可流動的麵糊，高麗菜切細，雞蛋打散。", "平底鍋抹油，煎薄麵糊並放上蛋與高麗菜，翻面煎至全熟後捲起。"], ["香菇、高麗菜及紅蘿蔔切碎。", "熟飯加水煮成粥，加入蔬菜煮軟，加鹽。"], ["雞肉、高麗菜及薑切碎。", "熟飯加水煮開，加入雞肉及蔬菜，煮至全熟、粥變稠後加鹽。"], ["雞蛋煮熟或煎熟，酪梨切片。", "純素小麥吐司稍烤，放上酪梨與蛋，加少許鹽。"], ["香蕉去皮切片。", "純素小麥吐司塗上花生醬，再鋪上香蕉。"], ["毛豆與玉米煮熟瀝乾，與熟飯及鹽拌勻。", "用乾淨器具捏成飯糰，包上原味海苔。"], ["雞蛋打散，番茄切丁。", "熱油炒蛋與番茄至熟，加鹽後夾入純素小麥吐司。"], ["小米洗淨，南瓜切小丁。", "加水小火煮至小米熟透、南瓜軟化，期間適度攪拌並補水。"], ["蘋果與香蕉洗淨去皮切塊。", "盛入原味優格，放上水果與南瓜子。"], ["地瓜洗淨，切成大小相近的小塊。", "放入蒸鍋，蒸至中心可輕鬆穿透。"], ["水煮開，加入毛豆煮熟。", "瀝乾後拌入少許鹽。"], ["香蕉去皮切片。", "將花生醬拌入原味優格，再加香蕉。"], ["蘋果洗淨去核切塊。", "與核桃一起盛杯。"], ["玉米放入水中煮熟。", "雞蛋另煮至全熟去殼，與玉米盛盤。"], ["蘋果洗淨去核，香蕉與奇異果去皮。", "切成適合入口的大小，立即盛盤。"], ["使用已煮熟的紅豆，加水煮開。", "加入少量糖，攪拌煮至溶解。"], ["馬鈴薯洗淨切薄瓣，拌入橄欖油與鹽。", "烤箱預熱至 200°C，烤約 20–25 分鐘至中心軟熟，依切塊大小調整。"]];
